// Function to return the length of a string.
int strlen(char *str) {
    int len = 0;
    while (*str != '\0') {
        str++;
        len++;
    }
    return len;
}

int main() {
    char buffer[100];
    char message[] = "Hello, World!";
    int bufferSize = sizeof(buffer);

    // Copy the message to the buffer.
