['Here's an example in C:

```c
#include <stdio.h>
#include <string.h>

// Function to copy n bytes from src to dest
void copy_bytes(void *dest, void *src, int n) {
    char *d = (char *)dest;
    char *s = (char *)src;

    for(int i=0; i<n; i++) {
        d[i] = s[i];
    }
}

// Function to find the length of a string
int string_length(char *str) {
    int len = 0;
    while(str[len] != '\0') {
        len++;
    }
    return len;
}

int main() {
    char buffer[20]; // Buffer to store the copied string

    strcpy(buffer, "Hello"); // Copy "Hello" to the buffer
    printf("Buffer: %s\n", buffer); // Print the buffer contents

    int length = string_length(buffer); // Find the length of the buffer
    printf("Length: %d\n", length);

    return 0;
}
```

In this code:

