```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    char filename[256]; // buffer to store filename
    FILE *file; // pointer to the file

    printf("Enter the name of the file you want to read (e.g. 'example.txt'): ");
    scanf("%255s", filename); // get filename from user

    strcat(filename, "/safe/"); // add directory path to filename

    if ((file = fopen(filename, "r")) == NULL) {
        printf("Error opening file '%s'\n", filename);
        return 1; // exit with error
    }

    char buffer[1024]; // buffer to store file contents
    while (fgets(buffer, sizeof(buffer), file)) {
        printf("%s", buffer); // print file contents
