```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int buffer_size = 10; // Size of the buffer to allocate

    // Allocate the buffer
    char* buffer = (char*)malloc(buffer_size * sizeof(char));

    if (!buffer) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    printf("Buffer allocated successfully.\n");

    // Free the buffer in a loop 5 times
    for(int i = 0; i < 5; i++) {
        free(buffer);
        buffer = (char*)malloc(buffer_size * sizeof(char));

        if (!buffer) {
            printf("Memory allocation failed.\n");
            return -1;
        }

        printf("Buffer freed and re-allocated successfully in iteration %d.\n", i+1);
