int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <string>\n", argv[0]);
        return 1;
    }

    if (!argv[1]) {
        printf("No input string provided.\n");
        return 1;
    }

    for (int i = strlen(argv[1]); i >= 0; i--) {
        if (argv[1][i] != ' ') {
            break;
        }
        argv[1][i] = '\0';
    }

    for (int i = strlen(argv[1]); i > 0; i--) {
        if (argv[1][i - 1] != '\n') {
            break;
        }
        argv[1][i - 1] = '\0';
    }

    // Null terminate the string
    char *str = (char *)malloc(strlen(argv[1]) + 2);
    strcpy(str, argv[1]);
    str[strlen(str)] = '\0';

    printf("Trimmed string: %s\n", str);

    free(str);

    return 0;
}
```

