#include <apr_strings.h>
#include <apr_tables.h>

void http_hello_page(request_rec r) {
    apr_file_t *file;
    char* username = NULL;
    char outputbuf[1024];

    /* Read the request body */
    if(apr_table_get(r->input_filters, "content_length") != NULL){
        int contentLength = apr_int64_to_long(apr_table_get(r->input_filters, "content_length"));
        apr_file_t *f = apr_file_open("memory://", APR_FILE_READWRITE);
        apr_file_setbuf(f, outputbuf, 1024);
        apr_file_read(f, r->input_filters, contentLength);
    }

    /* Read the username from the request body */
    if(apr_table_get(r->input_filters, "username") != NULL){
        username = apr_table_get(r->input_filters, "username");
    } else {
        ap_log_error(APLOG_ERR, r->srmODULE, "No username provided.\n");
        return;
    }

    /* Construct the response body (the HTML page) */
    apr_snprintf(outputbuf, 1024, "<html><body>Hello %s!</body></html>", username);

    /* Write the response body to the response stream */
    apr_table_set(r->output_filters, "content_length", "23"); // adjust this value based on your output
    ap_rwrite(outputbuf, strlen(outputbuf), r);

    /* Close the response stream */
    ap_finalize_rwrite(r);
}
