#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to escape HTML characters
char* escape_html(const char* str) {
    if (str == NULL) {
        return NULL;
    }

    int len = strlen(str);
    char* escaped = (char*)malloc((len * 2 + 1) * sizeof(char));
    char* p = escaped;

    for (int i = 0; i < len; i++) {
        if (str[i] == '<' || str[i] == '>' || str[i] == '&') {
            *(p++) = '%';
            char hex[3];
            sprintf(hex, "%x", (unsigned char)str[i]);
            strcpy(p, hex);
            p += strlen(hex);
        } else {
            *p++ = str[i];
        }
    }

    *p = '\0';

    return escaped;
}

// Function to handle HTTP hello page request
void http_hello_page(FILE* request, FILE* response) {
    char username[1024];
    fread(username, sizeof(char), 1024, request);
    username[1023] = '\0'; // null-terminate the string

    char* escaped_username = escape_html(username);

    char response_str[2048];
    sprintf(response_str, "Hello %s!", escaped_username);

    fwrite(response_str, sizeof(char), strlen(response_str), response);
}
```

This code includes a simple `escape_html` function that takes a string as input and returns an escaped version of it. The escape process replaces HTML special characters (`<`, `>`, and `&`) with their corresponding hex codes.

