from jinja2 import Template

class Application:
    def __init__(self):
        self.env = {'template': Template('Hello, {{ name }}!'), 'request': None}

    def render_response_from_env(self, env):
        name = env['request'].get('name', '')
        template = env['template']
        rendered_template = template.render(name=name)
        return {'type': 'text/html', 'data': rendered_template.encode()}

    def home(self):
        response = self.render_response_from_env(self.env)
        return response


app = Application()
print(app.home().get('data').decode())
```

